insert into public.recipes
  (source, slug, title, author, headnote, image_url, prep_minutes, cook_minutes, total_minutes, servings, tags, owner_id, published_at)
values
  ('seeded', 'beef-and-broccoli', 'Beef & Broccoli Stir-Fry', 'Pinched Kitchen', 'Tender sliced steak and crisp broccoli in a glossy ginger-garlic sauce. Whisk the sauce ahead and dinner is fast.', '/images/recipes/beef-and-broccoli.svg', 15, 15, 30, 4, array['dinner', 'dairy-free', 'high-protein', 'quick']::text[], null, null),
  ('seeded', 'berry-overnight-oats', 'Berry Overnight Oats', 'Pinched Kitchen', 'Four breakfasts in one bowl: stir, portion, chill. They keep for up to four days.', '/images/recipes/berry-overnight-oats.svg', 10, 0, 10, 4, array['breakfast', 'vegetarian', 'make-ahead', 'quick']::text[], null, null),
  ('seeded', 'black-bean-patties', 'Black Bean Patties', 'Pinched Kitchen', 'Crispy cumin-spiced black bean patties on buns with a cilantro yogurt sauce.', '/images/recipes/black-bean-patties.svg', 20, 15, 35, 4, array['dinner', 'vegetarian']::text[], null, null),
  ('seeded', 'black-bean-soup', 'Smoky Black Bean Soup', 'Pinched Kitchen', 'A thick, smoky soup from pantry staples. Blend half for a creamier texture.', '/images/recipes/black-bean-soup.svg', 10, 35, 45, 6, array['lunch', 'dinner', 'vegan', 'gluten-free', 'dairy-free', 'make-ahead']::text[], null, null),
  ('seeded', 'caprese-pasta-salad', 'Caprese Pasta Salad', 'Pinched Kitchen', 'Tomatoes, mozzarella and basil tossed with pasta. It tastes better after a night in the fridge.', '/images/recipes/caprese-pasta-salad.svg', 15, 10, 25, 6, array['lunch', 'vegetarian', 'make-ahead']::text[], null, null),
  ('seeded', 'chicken-fried-rice', 'Chicken Fried Rice', 'Pinched Kitchen', 'The best use for leftover rice. Cook the rice a day ahead and dinner takes ten minutes.', '/images/recipes/chicken-fried-rice.svg', 15, 15, 30, 4, array['dinner', 'dairy-free', 'high-protein', 'quick']::text[], null, null),
  ('seeded', 'chicken-rice-bowls', 'Chicken Rice Bowls', 'Pinched Kitchen', 'Soy-garlic chicken over rice with roasted sweet potatoes and a cool, lemony yogurt sauce. Most of it can be made on prep day.', '/images/recipes/chicken-rice-bowls.svg', 15, 30, 45, 4, array['dinner', 'high-protein', 'make-ahead']::text[], null, null),
  ('seeded', 'chickpea-coconut-curry', 'Chickpea Coconut Curry', 'Pinched Kitchen', 'Chickpeas and spinach simmered in a spiced coconut sauce. Fully plant-based and ready in forty minutes.', '/images/recipes/chickpea-coconut-curry.svg', 10, 30, 40, 4, array['dinner', 'vegan', 'gluten-free', 'dairy-free']::text[], null, null),
  ('seeded', 'chickpea-salad-sandwiches', 'Chickpea Salad Sandwiches', 'Pinched Kitchen', 'Crunchy, lemony and ready in fifteen minutes. The salad keeps for three days, so make a double batch.', '/images/recipes/chickpea-salad-sandwiches.svg', 15, 0, 15, 4, array['lunch', 'vegetarian', 'quick', 'make-ahead']::text[], null, null),
  ('seeded', 'creamy-tomato-soup', 'Creamy Tomato Soup', 'Pinched Kitchen', 'Pantry-friendly tomato soup that blends smooth in minutes. Good with a grilled cheese.', '/images/recipes/creamy-tomato-soup.svg', 10, 30, 40, 4, array['lunch', 'dinner', 'vegetarian', 'gluten-free']::text[], null, null),
  ('seeded', 'egg-muffins', 'Spinach & Pepper Egg Muffins', 'Pinched Kitchen', 'Grab-and-go egg cups you can bake once and reheat all week. Swap in whatever vegetables are in the fridge.', '/images/recipes/egg-muffins.svg', 10, 20, 30, 6, array['breakfast', 'vegetarian', 'gluten-free', 'make-ahead', 'high-protein']::text[], null, null),
  ('seeded', 'garlic-butter-shrimp', 'Garlic Butter Shrimp with Rice', 'Pinched Kitchen', 'Shrimp in a lemony garlic butter, ready in about twenty minutes.', '/images/recipes/garlic-butter-shrimp.svg', 10, 15, 25, 4, array['dinner', 'pescatarian', 'quick']::text[], null, null),
  ('seeded', 'garlic-spinach-pasta', 'Garlic Spinach Pasta', 'Pinched Kitchen', 'Penne tossed with garlicky wilted spinach, lemon and Parmesan. Fifteen minutes of actual cooking.', '/images/recipes/garlic-spinach-pasta.svg', 10, 15, 25, 4, array['dinner', 'vegetarian', 'quick']::text[], null, null),
  ('seeded', 'lemon-herb-chicken-green-beans', 'Lemon Herb Chicken with Green Beans', 'Pinched Kitchen', 'Pan-seared chicken breasts with a quick lemon-parsley pan sauce, served with buttery green beans.', '/images/recipes/lemon-herb-chicken-green-beans.svg', 10, 25, 35, 4, array['dinner', 'gluten-free', 'high-protein']::text[], null, null),
  ('seeded', 'lentil-vegetable-soup', 'Lentil Vegetable Soup', 'Pinched Kitchen', 'A sturdy, plant-based soup that only gets better on day two. A squeeze of lemon at the end wakes it up.', '/images/recipes/lentil-vegetable-soup.svg', 15, 40, 55, 6, array['lunch', 'dinner', 'vegan', 'gluten-free', 'dairy-free', 'make-ahead']::text[], null, null),
  ('seeded', 'miso-glazed-cod', 'Miso-Glazed Cod', 'Pinched Kitchen', 'Broiled cod with a sweet-salty miso glaze, served with rice and bok choy. Dinner in about twenty-five minutes.', '/images/recipes/miso-glazed-cod.svg', 10, 15, 25, 2, array['dinner', 'pescatarian', 'dairy-free', 'quick']::text[], null, null),
  ('seeded', 'peanut-butter-waffles', 'Peanut Butter Waffles with Banana', 'Pinched Kitchen', 'Crisp, nutty waffles with a soft middle. The dry ingredients can be whisked together ahead of time.', '/images/recipes/peanut-butter-waffles.svg', 10, 15, 25, 4, array['breakfast', 'vegetarian']::text[], null, null),
  ('seeded', 'quinoa-black-bean-bowls', 'Quinoa Black Bean Bowls', 'Pinched Kitchen', 'Fluffy quinoa, beans, corn and a bright lime dressing. Pack it cold for lunch.', '/images/recipes/quinoa-black-bean-bowls.svg', 15, 15, 30, 4, array['lunch', 'vegan', 'gluten-free', 'dairy-free', 'make-ahead']::text[], null, null),
  ('seeded', 'salmon-bowls', 'Salmon Bowls', 'Pinched Kitchen', 'Seared salmon over rice with cucumber, avocado and a soy-sesame dressing. The dressing keeps for days.', '/images/recipes/salmon-bowls.svg', 10, 20, 30, 2, array['dinner', 'pescatarian', 'dairy-free', 'quick']::text[], null, null),
  ('seeded', 'sesame-peanut-noodles', 'Sesame Peanut Noodles', 'Pinched Kitchen', 'Cold noodles in a savory peanut-sesame sauce with crisp cucumber. Good warm too, and they keep well for lunch.', '/images/recipes/sesame-peanut-noodles.svg', 15, 10, 25, 4, array['lunch', 'dinner', 'vegan', 'dairy-free', 'quick', 'make-ahead']::text[], null, null),
  ('seeded', 'shakshuka', 'Shakshuka', 'Pinched Kitchen', 'Eggs poached in a spiced tomato and pepper sauce. One skillet, breakfast or dinner.', '/images/recipes/shakshuka.svg', 10, 30, 40, 4, array['breakfast', 'dinner', 'vegetarian', 'one-pan']::text[], null, null),
  ('seeded', 'sheet-pan-chicken-fajitas', 'Sheet-Pan Chicken Fajitas', 'Pinched Kitchen', 'Chicken, peppers and onions roasted with a chili-cumin rub, served in warm tortillas.', '/images/recipes/sheet-pan-chicken-fajitas.svg', 15, 20, 35, 4, array['dinner', 'dairy-free', 'one-pan']::text[], null, null),
  ('seeded', 'sheet-pan-chicken-sweet-potatoes', 'Sheet-Pan Chicken & Sweet Potatoes', 'Pinched Kitchen', 'Garlic-lemon chicken thighs roasted on one pan with sweet potatoes, red onion and broccoli. Minimal dishes.', '/images/recipes/sheet-pan-chicken-sweet-potatoes.svg', 15, 35, 50, 4, array['dinner', 'gluten-free', 'dairy-free', 'one-pan']::text[], null, null),
  ('seeded', 'sheet-pan-sausage-vegetables', 'Sheet-Pan Sausage & Vegetables', 'Pinched Kitchen', 'Smoked sausage, potatoes and broccoli roasted together until browned at the edges. Easy cleanup.', '/images/recipes/sheet-pan-sausage-vegetables.svg', 15, 30, 45, 4, array['dinner', 'one-pan']::text[], null, null),
  ('seeded', 'sweet-potato-black-bean-hash', 'Sweet Potato & Black Bean Hash with Eggs', 'Pinched Kitchen', 'A one-skillet hash that works for breakfast or dinner. The eggs cook right on top.', '/images/recipes/sweet-potato-black-bean-hash.svg', 15, 25, 40, 4, array['breakfast', 'dinner', 'vegetarian', 'gluten-free', 'one-pan']::text[], null, null),
  ('seeded', 'sweet-potato-black-bean-tacos', 'Sweet Potato & Black Bean Tacos', 'Pinched Kitchen', 'Roasted sweet potatoes and warm black beans in corn tortillas, finished with lime and cilantro.', '/images/recipes/sweet-potato-black-bean-tacos.svg', 15, 30, 45, 4, array['dinner', 'vegan', 'gluten-free', 'dairy-free']::text[], null, null),
  ('seeded', 'tomato-pasta', 'Simple Tomato Pasta', 'Pinched Kitchen', 'A weeknight spaghetti with soft, garlicky tomatoes and plenty of basil. Nothing fancy, always welcome.', '/images/recipes/tomato-pasta.svg', 10, 25, 35, 4, array['dinner', 'vegetarian']::text[], null, null),
  ('seeded', 'turkey-chili', 'Turkey Chili', 'Pinched Kitchen', 'A big pot of mild, hearty chili that feeds a crowd and freezes well.', '/images/recipes/turkey-chili.svg', 15, 50, 65, 6, array['dinner', 'gluten-free', 'dairy-free', 'make-ahead', 'high-protein']::text[], null, null),
  ('seeded', 'turkey-patties', 'Turkey Patties with Yogurt Sauce', 'Pinched Kitchen', 'Herby turkey patties with a cool cucumber-dill sauce. The sauce and the chopping can be done ahead.', '/images/recipes/turkey-patties.svg', 15, 15, 30, 4, array['dinner', 'high-protein']::text[], null, null),
  ('seeded', 'turkey-stuffed-peppers', 'Turkey Stuffed Peppers', 'Pinched Kitchen', 'Bell peppers filled with seasoned turkey and rice, baked until tender with melted mozzarella on top.', '/images/recipes/turkey-stuffed-peppers.svg', 20, 55, 75, 4, array['dinner', 'gluten-free', 'high-protein', 'make-ahead']::text[], null, null),
  ('seeded', 'vegetable-soup', 'Hearty Vegetable Soup', 'Pinched Kitchen', 'A big pot of vegetables, white beans and greens. It freezes beautifully, so portion what you won''t eat this week.', '/images/recipes/vegetable-soup.svg', 15, 40, 55, 6, array['lunch', 'dinner', 'vegan', 'gluten-free', 'dairy-free', 'make-ahead']::text[], null, null),
  ('seeded', 'veggie-breakfast-burritos', 'Veggie Breakfast Burritos', 'Pinched Kitchen', 'Eggs, black beans and peppers rolled up tight. Wrap them individually and reheat from the fridge or freezer.', '/images/recipes/veggie-breakfast-burritos.svg', 15, 15, 30, 4, array['breakfast', 'vegetarian', 'make-ahead']::text[], null, null),
  ('seeded', 'weeknight-chicken-curry', 'Weeknight Chicken Curry', 'Pinched Kitchen', 'A mild, creamy curry built from pantry staples. Serve over rice with plenty of cilantro.', '/images/recipes/weeknight-chicken-curry.svg', 15, 30, 45, 4, array['dinner', 'gluten-free', 'dairy-free']::text[], null, null)
on conflict (slug) where source = 'seeded' do update set
  title = excluded.title,
  author = excluded.author,
