  ('sweet-potato-black-bean-hash', 2, 'Cook the sweet potatoes for 10 minutes, stirring occasionally, until browned.'),
  ('sweet-potato-black-bean-hash', 3, 'Add the onion, bell pepper, paprika and salt and cook 6 minutes more.'),
  ('sweet-potato-black-bean-hash', 4, 'Stir in the beans. Make four wells, crack an egg into each, cover and cook 4 minutes.'),
  ('sweet-potato-black-bean-hash', 5, 'Top with the cilantro.'),
  ('sweet-potato-black-bean-tacos', 1, 'Toss the sweet potatoes with the oil, chili powder, cumin and salt. Roast at 425°F for 25 minutes, until tender and browned.'),
  ('sweet-potato-black-bean-tacos', 2, 'Warm the beans in a small saucepan over low heat.'),
  ('sweet-potato-black-bean-tacos', 3, 'Warm the tortillas in a dry skillet.'),
  ('sweet-potato-black-bean-tacos', 4, 'Fill the tortillas with the sweet potatoes and beans and top with the red onion, cilantro, sliced avocado and a squeeze of lime.'),
  ('tomato-pasta', 1, 'Bring a large pot of salted water to a boil.'),
  ('tomato-pasta', 2, 'Warm the olive oil in a large skillet over medium heat. Cook the onion and garlic until soft, about 6 minutes.'),
  ('tomato-pasta', 3, 'Add the tomatoes, crushing them with a spoon, and simmer for 15 minutes.'),
  ('tomato-pasta', 4, 'Cook the spaghetti until al dente. Toss with the tomatoes, basil and Parmesan.'),
  ('turkey-chili', 1, 'Warm the oil in a large pot over medium heat. Cook the onion and pepper until soft, about 8 minutes, then add the garlic for 1 minute.'),
  ('turkey-chili', 2, 'Add the turkey and cook, breaking it up, until no longer pink, about 8 minutes.'),
  ('turkey-chili', 3, 'Stir in the chili powder and cumin, then the tomatoes, beans, broth and salt.'),
  ('turkey-chili', 4, 'Simmer for 30 minutes, stirring occasionally. Season to taste.'),
  ('turkey-patties', 1, 'Mix the turkey, onion, garlic, egg, panko and salt and form into 8 patties.'),
  ('turkey-patties', 2, 'Stir the yogurt, cucumber, lemon juice and dill together into a sauce.'),
  ('turkey-patties', 3, 'Cook the patties in the oiled skillet over medium-high heat, 5 minutes per side, until cooked through.'),
  ('turkey-patties', 4, 'Serve warm with plenty of sauce.'),
  ('turkey-stuffed-peppers', 1, 'Cook the rice according to the package directions.'),
  ('turkey-stuffed-peppers', 2, 'Heat the oven to 375°F. Cut the tops off the peppers, remove the seeds and stand the peppers in a baking dish.'),
  ('turkey-stuffed-peppers', 3, 'Warm the oil in a skillet over medium heat. Cook the onion for 5 minutes, then add the garlic and turkey and cook until browned, about 8 minutes.'),
  ('turkey-stuffed-peppers', 4, 'Stir in the rice, half the tomato sauce, the Italian seasoning and the salt. Spoon into the peppers.'),
  ('turkey-stuffed-peppers', 5, 'Pour the remaining sauce over the top, cover with foil and bake for 30 minutes. Uncover, sprinkle with the mozzarella and bake 10 minutes more.'),
  ('vegetable-soup', 1, 'Heat the oil in a large pot over medium heat. Cook the onion, carrots and celery until soft, about 10 minutes.'),
  ('vegetable-soup', 2, 'Add the garlic, tomatoes and broth. Simmer for 25 minutes, crushing the tomatoes with a spoon.'),
  ('vegetable-soup', 3, 'Stir in the white beans and spinach and cook until the spinach wilts. Season to taste.'),
  ('veggie-breakfast-burritos', 1, 'Warm the oil in a large skillet over medium heat. Cook the bell pepper and onion until soft, about 6 minutes.'),
  ('veggie-breakfast-burritos', 2, 'Add the beans and cumin and cook 2 minutes more.'),
  ('veggie-breakfast-burritos', 3, 'Beat the eggs with the salt, pour into the skillet and stir gently until just set.'),
  ('veggie-breakfast-burritos', 4, 'Divide the filling among the tortillas, top with the cheddar and salsa, and roll up tightly.'),
  ('veggie-breakfast-burritos', 5, 'Wrap each burrito in foil and refrigerate for up to 4 days, or freeze for up to 2 months.'),
  ('weeknight-chicken-curry', 1, 'Cook the rice according to the package directions.'),
  ('weeknight-chicken-curry', 2, 'Warm the oil in a large pot over medium heat. Cook the onion until soft, about 6 minutes, then stir in the garlic, ginger and curry powder for 1 minute.'),
  ('weeknight-chicken-curry', 3, 'Add the chicken, tomatoes, coconut milk and salt. Simmer for 20 minutes, until the chicken is cooked through and the sauce has thickened.'),
  ('weeknight-chicken-curry', 4, 'Serve over the rice, topped with the cilantro.')
) as v(slug, step_number, instruction)
join public.recipes r on r.source = 'seeded' and r.slug = v.slug;
